# Each row is a reasoned candidate, not a mechanically generated hypothesis.
R=[]
def screen(i,lens,src,disposition,card,predicate,comparison,gate):
 R.append(dict(candidate_id=i,lens=lens,source_ids=src,disposition=disposition,card_or_prior=card,predicate=predicate,semantic_novelty_or_rejection=comparison,discriminating_evidence_and_next_check=gate))
screen('C1','conserved_quantities',[255,5],'new','B01','Material plant-performance claim relies on generation incompatible with all measured energy inputs','R13 compares fuel/emissions; N09 compares company output with national production. This tests a conversion balance, not a peer-efficiency benchmark.','Exact physical boundary, full consumed-energy inputs, lower output/upper input bounds and current corrections; reject hybrid/storage/imported-heat ambiguity.')
screen('C2','conserved_quantities',[185,186,188,187],'reject','C09','Evapotranspiration greater than rainfall proves illegal pumping','ET also reflects stored soil water, groundwater and authorized irrigation; GRACE scale is not field pumping.','Need measured abstraction, rights, soil/storage and inflows; reject rainfall-only subtraction as a legal test.')
screen('C3','conserved_quantities',[82,83],'defer','none','Arms inventory change fails deliveries-minus-losses balance','SIPRI transfer estimates and UNROCA reports do not establish opening stocks, domestic production, losses or complete coverage.','Obtain actual weapon-unit stocks and all flows; no conversion of SIPRI trend-indicator values to weapon counts.')
screen('C4','conserved_quantities',[231,232,233],'reject','none','Adding displacement flows and refugee stocks proves inflated beneficiary numbers','Movements, persons and point-in-time stocks are different units; repeated displacement is real.','Define unique-person population and dates with coverage before reconciliation; no individual identity data acquired.')
screen('M1','mutually_exclusive_statuses',[72,73,280],'defer','none','Same ship has two purported current national registrations','IMO may anchor identity, but charter registration, suspension and different registry roles defeat a naive flag conflict.','Need historical official instruments establishing simultaneously operative incompatible status; Equasis snapshot is not enough.')
screen('M2','mutually_exclusive_statuses',[151,147,262],'reject','none','Two ASNs announce one prefix therefore one stole it','Multiple-origin announcements can be authorized, including transition and anycast arrangements.','Need holder authorization, routing-security evidence and dated configuration; RDAP ownership alone does not settle origin legitimacy.')
screen('M3','mutually_exclusive_statuses',[279],'reject','none','Same frequency and overlapping service geometry mean unlawfully duplicated licences','Frequency reuse, antenna patterns, power, time, service and coordination conditions matter.','Obtain exact operative licence terms and engineering interference evidence; point overlap is not exclusivity.')
screen('M4','mutually_exclusive_statuses',[302,309,314,288],'refinement_deferred','Z04/X09','Two issuers claim exclusive ownership of the same mineral right','Refines Z04 incompatible exclusive grants and X09 title assertions; changing asset type does not add a mechanism.','Same jurisdiction, tenure number, right type, depth/commodity, effective dates and chain; different provinces or surface/mineral interests are not conflicting rights.')
screen('P1','prerequisites_sequence',[52,145],'reject','none','Payment preceding goods delivery proves improper procurement','Advance/mobilization payments may be expressly allowed; milestone due dates are not actual delivery dates.','Read payment clause, security and amendments; discard blanket pay-after-delivery assumption.')
screen('P2','prerequisites_sequence',[248,250],'refinement_deferred','X07','First participant enrollment precedes required ethics approval','Another required-approval-before-action predicate; registry start date may be estimated and publication ethics text incomplete.','Actual first enrollment, original approval/version and applicable local rule or waiver required; no generic global deadline.')
screen('P3','prerequisites_sequence',[84,82,83],'reject','none','Arms delivery before a DSCA announcement proves unauthorized export','Announcements, approvals, commercial licences, earlier cases, amendments and deliveries are not one universal sequence.','Require exact transmittal/licence and shipment identity plus applicable regime; aggregate country/system match is insufficient.')
screen('P4','prerequisites_sequence',[59,145,58],'refinement_deferred','X07','Withdrawal made before a project-specific disbursement condition was satisfied','Useful X07 prerequisite variant, not a new formulation merely because action is disbursement.','Original financing condition, category, bank notice, waiver and actual withdrawal effective date; project approval or headline commitment is not withdrawal.')
screen('B1','beneficial_interest_conflicts',[122,119,4,10],'refinement','REF-MEP','File-specific no-conflict statement versus a dated private interest tied to the matter','Refines H04 and REF-REL disclosure consistency; actual official role and interest must connect to this file.','Member ID/procedure → signed file-specific statement → verified company/role/interest dates; no generic employer-name inference.')
screen('B2','beneficial_interest_conflicts',[52,108,4],'refinement_deferred','E08','Procurement decision maker benefits through the selected supplier','Role-versus-beneficiary overlap is the related-party decision-maker predicate E08, not new simply in procurement.','Actual decision authority and beneficial interest at decision date; same address or officer name is insufficient; declaration/recusal rules separate.')
screen('B3','beneficial_interest_conflicts',[45,46,3],'repeat','E08','Charity trustee connected to grantee','Already covered by E08 related-party transactions.','Retain jurisdiction-specific reporting rules for future implementation, but do not create another card from source substitution.')
screen('B4','beneficial_interest_conflicts',[119,122],'defer','none','Listed lobbyist simultaneously holds an incompatible parliamentary role','Register contact names do not prove employment duties or incompatibility; paid/outside roles and rules differ.','Exact person identity, actual role dates and operative restriction plus permission; no name-only accusation.')
screen('D1','double_claims',[145,59,52,57],'new','B02','Independent completed reimbursements charged to the same eligible cost exceed its permitted funding','N01 reconciles aid accounts; Z01 bid rates; X02 unpaid obligations. This tests duplicate cost recovery after reconstructing the money path.','Original cost item and financing cap; independent settled payments net of refunds, not mirrored donor/recipient entries or pass-through transfers.')
screen('D2','double_claims',[5,288,133],'defer','none','Two offset claims consume the same carbon-credit units','Issuer claims and snapshots do not establish serial-level issuance/retirement rights. No registry crosswalk established in this batch.','Acquire exact registry, unit serial interval, vintage, beneficiary and claim text; resale, scope and revisions matter. Supporting registry required before a card.')
screen('D3','double_claims',[245,246,249,250],'reject','none','Two grants credited for one paper proves duplicate reimbursement','Multiple grants can lawfully support one output; acknowledgement is not cost accounting.','Actual same charged cost, funded share and prohibition required; use B02 only if that evidence exists, not publication counts.')
screen('D4','double_claims',[255,5,288],'refinement_deferred','Z04','Two parties claim the same exclusive renewable-power attribute','Underlying electricity, certificates and environmental claims can be separate rights; exclusivity overlap refines Z04.','Exact certificate serials or unique metered MWh and contract attribute clauses; same generator/year is not the same right.')
screen('R1','operation_vs_representation',[281,280,288],'refinement_deferred','P05','An expressly serviceable vessel is documented as lost before the claim date','Precise operational assertion versus established finding refines P05; mere continuing registry entry makes no serviceability claim.','Final occurrence facts, exact vessel identity, salvage/reconstruction and representation date; no all-registry-is-active assumption.')
screen('R2','operation_vs_representation',[255,5,217],'refinement_deferred','R13/C01','Exact no-fossil-input generation claim versus recorded fuel consumption','Fuel/energy/emissions representation specialization; no separate formulation counted.','Claim may concern contracted attributes or net accounting rather than physical inputs; match site, interval and explicit scope.')
screen('R3','operation_vs_representation',[145,109,101],'repeat','Z02/P05','Completed physical asset claim versus incompatible dated site evidence','Already represented by physical-inventory and precise-assertion methods.','Optical nonvisibility is not nonexistence; exact claimed date, footprint and construction stage required.')
screen('R4','operation_vs_representation',[230,283],'repeat','C13','Assessment claims no relevant species records despite a verified occurrence','C13 already tests omitted scoped occurrences.','Taxon, observation quality, coordinate uncertainty, survey cutoff and legal relevance; no sensitive coordinates disclosed.')
C=[]
def add(i,title,kind,primary,support,initial,expected,basis,join,scope,ordinary,evidence,cheap,novelty,docs,scores,access):
 C.append(dict(test_id=i,title=title,kind=kind,primary_source_ids=primary,supporting_source_ids=support,initial_observation=initial,expected_observation=expected,basis=basis,operational_join=join,temporal_geographic_scope=scope,ordinary_explanations_and_disqualifiers=ordinary,mandatory_evidence=evidence,next_cheapest_check=cheap,novelty_comparison=novelty,documentation_ids=docs,consequence=scores[0],testability=scores[1],join_route=scores[2],cost_tier=scores[3],access_evidence=access,execution_status='not_executed',positive_finding=False,case_rule_applicability_verified=False,complete_route_feasible=False))
add('B01','Material plant-performance claims versus a complete energy-conversion balance','proposed_new',[255,5],[],
'IF a material financing, subsidy or operating-performance claim identifies an exact fuel-fired plant and reporting interval, and comparable official generation and total consumed-energy records are available for its complete physical boundary.',
'THEN test whether even a conservative lower bound on electrical energy produced exceeds a conservative upper bound on all energy inputs, after resolving revisions and boundary flows. An unresolved excess identifies incompatible evidence requiring correction or explanation, not automatically fraud.',
'Energy conservation supplies a physical bound, unlike a discretionary industry-efficiency benchmark. Net generation converted to energy cannot exceed all consumed inputs over a closed, reconciled system interval. Finite storage changes and every external energy contribution must be bounded. A ratio below the bound says nothing about honest reporting or economic efficiency.',
'Issuer CIK/accession and exact plant passage → documented facility/operator/location crosswalk → EIA plant code, year/month, prime mover and fuel/source rows. Aggregate each physical input/output once; reconcile combined-cycle combustion and steam equipment so recovered internal heat is not new external input. A company name or regional series is not a plant match.',
'US EIA-covered plants with fuel-only generation and a verified boundary. Begin with a simple non-CHP plant; defer CHP, hybrid solar/wind, pumped/battery storage, nuclear, imported steam or waste heat unless every contribution and allocation is independently reconciled. Use consumed fuel, not purchases; use full total fuel input, not only fuel statistically allocated to electricity. Same period and corrected filing vintage.',
['Missing fuel/source or unit','Fuel purchases confused with consumption','Electricity receipts or sales confused with generation','Heat-content basis or unit conversion mismatch','Gross/net/direct-use differences','Rounding or uncertainty explains excess','Thermal or electrical stored-energy release','Internal recovered steam double-counted','Plant/prime-mover boundary mismatch','Revised or estimated data','Claim refers to contractual attributes rather than physical performance'],
['Original material claim and its exact metric','Plant identity crosswalk','Complete generation and all energy-input records for matching boundary/period','Data definitions, heat-content basis and revision history','Evidence excluding or measuring imported energy and storage changes','Conservative output/input bounds and tolerance'],
'Read the claim and plant technology first; reject an economic or certificate claim that makes no physical assertion. Inspect one plant-period schema and all source codes before calculating. Stop if complete input or boundary evidence is unavailable.',
'R13 and C01 compare emissions with activity; N09 uses national production as an external upper bound. B01 is a complete physical conversion-balance test with materially different input evidence. One proposed formulation; different fuels, months and plants are implementations, not new tests.', ['D01','D02','D03'],[5,2,2,2],
'Current EIA form instructions and public data documentation inspected. Field meanings and bulk publication are confirmed; no plant rows or issuer-to-plant crosswalk were acquired. Current instructions separate consumption, generation and incoming electricity. No end-to-end feasibility established.')
add('B02','The same eligible cost reimbursed beyond its permitted funding','proposed_new',[145,59],[52,57],
'IF operative financing instruments permit reimbursement only up to a specified eligible cost/share, and original evidence attributes two or more independent completed reimbursements to the same uniquely identified cost item.',
'THEN reconstruct each payment path, permitted sharing, credits and reversals and compare the conservative lower bound of distinct net reimbursements with the conservative upper bound of the permitted reimbursable cost. Retain an unresolved excess for source-document review.',
'This is an instrument-specific cost-recovery constraint. Two project commitments or two descriptions of one transfer are not two recoveries. A payable supplier invoice can legitimately be financed through several parties, and authorized cofinancing can split its cost. No universal prohibition across all grant or results-based funding is asserted.',
'World Bank project ID → exact loan/credit ID and original financing/disbursement documents → expenditure schedule/audit and uniquely identified invoice/cost item (issuer, invoice number/date, line, amount/currency) → actual settled payment references and payer/payee chain. OCDS transaction source/URI and IATI activity/transaction references can trace mirrored or onward flows, but neither necessarily publishes invoice-level identity. A shared project ID is only discovery.',
'Exact instrument, category, funded share, eligible-cost period and accounting/currency basis. Exclude results-based or unrestricted funding unless its own terms impose this cost cap. Resolve advance liquidation, prefinancing reimbursement, retention, tax, exchange rates, partial credit notes and corrections. Use historical records current to each payment.',
['Same transfer mirrored by donor and recipient','Pass-through financing counted at each stage','Advance later liquidated rather than new money','Permitted cofinancing within cost/share','Invoice number reused by different vendors or years','Credit note/refund','Different cost lines or phases','Commitment mistaken for payment','Currency or tax basis differs','Results-based payment not cost reimbursement','Revised schedule republishes old expenditure'],
['Operative cost/share cap in every relevant financing instrument','Original eligible cost and adjustments','Evidence linking each claimed recovery to exactly that cost','Independent settlement records or an authoritative audit establishing payment','Full transfer-chain and correction/refund evidence','Conservative compatible-currency bounds'],
'Open a public project audit or expenditure schedule and establish whether it names the same cost and actual financing sources. If only project-level totals are published, defer before summing anything. No requests or full investigations are initiated.',
'N01 is aid-report reconciliation, X02 payment-obligation reconciliation and Z01 bid-rate arithmetic. This tests multiple independent recoveries against one constrained underlying cost. It is one proposed new formulation, not one per funding pair. When the funding terms do not constrain cost recovery, reject.', ['D04','D05','D06'],[5,1,2,3],
'World Bank disbursement guidance confirms several payment methods and supporting-document types; OCDS and IATI definitions supply possible flow links. Public availability of the needed original invoices, settlements and complete financing chain has not been established. Zero matched projects or cost items.')
add('REF-MEP','A file-specific no-conflict declaration versus a verified private interest','refinement',[122,119],[4,10],
'IF a member expressly declares no conflict for a specific parliamentary file and dated evidence establishes an actual private financial or organizational interest affected by that precise matter.',
'THEN reconcile the exact member, file, declared scope, interest type and dates, plus any disclosure, authorization or resolution, before describing an unresolved inconsistency in the statement.',
'A hidden relevant private interest can affect public trust in a legislative decision. A broad sector interest, a disclosed role, or a register contact name alone does not establish a prohibited conflict. Permission to act despite a disclosed conflict is distinct from a false no-conflict statement.',
'EP member ID and procedure/document ID → original signed file-specific declaration and actual role → dated company registration/role/ownership evidence. EU Transparency Register ID links an organization or client, not an individual beneficial owner. Resolve the person beyond name and distinguish employer, director, shareholder and contact roles.',
'Specific file and declaration/appointment interval. Use operative rules at that date; older codes differ. Not every private interest is a conflict and public asset declarations are not assumed available. No automatic recusal requirement is asserted.',
['Namesake','Role or ownership ended earlier','Only broad-class interest','Interest already within declared scope','No affirmative no-conflict assertion','Disclosed conflict with permitted participation','Register contact not beneficial owner','Different legal entity or legislative file'],
['Exact original declaration and file','Member identity and role dates','Verified private interest and economic relevance to the file','Applicable dated definition and declaration scope','Other disclosures, amendments and any permission/resolution'],
'Find the original file-specific statement before searching company names. If it is absent, do not infer a denial. Establish one documented member-to-entity bridge before broad ownership exploration.',
'Refinement of H04 conflict disclosure and REF-REL explicit relationship flags. This provides an additional legislative implementation route without adding to the non-refinement total.', ['D07','D08'],[5,1,1,3],
'Official search-index text, including a dated 2024 rules excerpt, identifies declaration routes and limits. Both current and dated PDF opens returned unusable HTML pages. No actual member, declaration, company interest or case-specific rule matched; access failure preserved.')
for c in C:
 c['source_manifest']=[{k:S[n][k] for k in ['sys_id','name','join_fields','all_ap_ids','file','line_start','line_end','block_sha256']} for n in dict.fromkeys(c['primary_source_ids']+c['supporting_source_ids'])]
 c['score']=10*c['consequence']+3*c['testability']+2*c['join_route']-2*c['cost_tier']
for label,key in [('priority_rank',lambda c:(-c['score'],c['test_id'])),('testability_rank',lambda c:(-c['testability'],c['cost_tier'],c['test_id'])),('consequence_rank',lambda c:(-c['consequence'],c['test_id']))]:
 for n,c in enumerate(sorted(C,key=key),1):c[label]=n
C.sort(key=lambda c:c['priority_rank'])
def export(name,rows):
 (P/(name+'.jsonl')).write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in rows))
 with (P/(name+'.csv')).open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows({k:json.dumps(v,ensure_ascii=False) if isinstance(v,(dict,list)) else v for k,v in r.items()} for r in rows)
export('cards',C);export('candidate-screen',R)
(P/'sources.jsonl').write_text((P.parent/'consequential-expansion-04/sources.jsonl').read_text())
